import hashlib,json,pathlib
from fixed_data_generate import symbols,fixed_address,rope_word,listing_records
R=pathlib.Path(__file__).resolve().parents[1]
def main():
 work=R/'build/sband-source/Comanche055';sy=symbols((work/'assembly.lst').read_text());rope=(work/'MAIN.agc.bin').read_bytes();audit=next(x for x in json.loads((R/'build/sband-source/audit.json').read_text())if x['source_path'].startswith('Comanche055/'))
 selected=[x for x in audit['source_line_word_map']if x['words']and 0o3724<=int(x['assembled_address'].split(',')[-1],8)<0o3750];assert sum(len(x['words'])for x in selected)==20
 path='Comanche055/INTERPRETIVE_CONSTANTS.agc';original=R.parent/path;assert original.read_bytes()==(work/'INTERPRETIVE_CONSTANTS.agc').read_bytes();records=listing_records(work/'assembly.lst',{'INTERPRETIVE_CONSTANTS.agc':path},{path:original.read_text()},rope)
 constants={}
 for label,count,expected in [('HIUNITX',6,[0o20000,0,0,0,0,0]),('HIUNITY',6,[0,0,0o20000,0,0,0]),('HIUNITZ',6,[0,0,0,0,0o20000,0]),('DPPOSMAX',2,[0o37777,0o37777]),('HIDP1/4',2,[0o10000,0])]:
  at=fixed_address(sy[label]);words=[rope_word(rope,at+i)for i in range(count)];assert words==expected;data=[x for x in records if x['words']and x['physical_fixed_word']is not None and at<=x['physical_fixed_word']<at+count];assert sum((x['words']for x in data),[])==words;constants[label]=dict(address=sy[label],physical_fixed_word=at,words=words,source_line_word_map=data)
 result=dict(source_path=audit['source_path'],source_sha256=audit['source_sha256'],rope_sha256=audit['rope_sha256'],source_edits=0,containing_file_status='partial',native_source='src/sband_cm_angles.c',source_words=20,source_line_word_map=selected,constants=constants,constant_source_path=path,constant_source_sha256=hashlib.sha256(original.read_bytes()).hexdigest(),scope='Complete original CM yaw and pitch computation from normal-plane NEWOPS; separate actual null-plane NOADJUST entry. Ends before original EXIT or source1301/1302 service. Local body operators execute explicitly, not decoded.',alias_contract='PUSH savesURP; PDVL pushesyaw and reloadsURP; negative yaw pops thenrepushes while retainingold destinationminorL. PitchSTODL/RHOSB and STORE/GAMMASB retainold destinationminorL. Canonical VAC/scratch aliases remain authoritative.',caller_controls='Original NEWOPS FB/BANKSET064000+EB, SUPER100/120/140/160, coherentEBBB, NEWJOB+0, ordinaryRAM/Q/rawA/L; fiveVAC normalMODE-1/PUSHbase+016 or nullMODE-1/PUSHbase+016. Successful yaw producesMODE0/PUSHbase+026 forpitch.',coverage='65536 normal-yaw and65536 null-pitch inputs, complete rawA/L/ordinaryQ marginals perentry; varied ordinaryvectors/flags andsignedzeros, fiveVAC/eightEB/fourSUPERforms/bothIRQ. NotexhaustiveCartesian.',private_shift='ActualSL1 sourceSHORTT/TSSL/SR/CYR plusfrozen rawscalar shift; no generic shortshift APIclaim.',branch='Original BRANCH TCQ positive returnsQ3 after actual register-Q fetch, INDEXQ TC1 zeroQ06710, TC2 negativeQ06712. Only these fixed source controls are compiled.')
 (R/'build/sband-cm-angles-source-map.json').write_text(json.dumps(result,indent=2)+'\n');print('PASS original CM20word yaw/pitch map plusfive exact literal objects')
